button:focus-visible {
  outline: 3px solid var(--focus-color);
  outline-offset: 2px;
}
/* antywzorzec */
*:focus { outline: none; }

const dialog = document.querySelector('dialog')!;
let opener: HTMLElement | null = null;

function open() {
  opener = document.activeElement as HTMLElement;
  dialog.showModal();          // focus trap + Esc + tło inert
}
dialog.addEventListener('close', () => opener?.focus());

*, *::before, *::after {
  box-sizing: border-box;
}
.card { width: 300px; padding: 16px; border: 1px solid; }
/* szerokość wizualna = 300px */

@layer reset, vendor, components, utilities;

@import url('lib.css') layer(vendor);

@layer components {
  .btn { padding: .5rem 1rem; }
}
@layer utilities {
  .p-0 { padding: 0; }   /* wygrywa z .btn mimo równej specificity */
}

/* szkielet strony */
.layout {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-areas: "side main";
}
/* pasek w nagłówku */
.toolbar { display: flex; align-items: center; gap: .5rem; }
.toolbar .spacer { margin-left: auto; }

.row { display: flex; }
.row .title {
  flex: 1;
  min-width: 0;            /* pozwala się skurczyć */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.card { position: relative; }
.card .badge { position: absolute; top: 8px; right: 8px; }
.header { position: sticky; top: 0; z-index: 10; }

/* nagłówek */
.header  { position: sticky; top: 0; z-index: 10; }
/* rodzic modala tworzy kontekst przez transform */
.panel   { transform: translateX(0); }
.panel .modal { position: fixed; z-index: 9999; } /* i tak pod .header */

.hero { min-height: 100svh; }
.app  { height: 100dvh; }

h1 {
  /* min 1.75rem, rośnie z viewportem, max 3rem */
  font-size: clamp(1.75rem, 1.2rem + 2vw, 3rem);
}

/* bazowo: jedna kolumna */
.layout { display: grid; gap: 1rem; }

@media (min-width: 48rem) {
  .layout { grid-template-columns: 16rem 1fr; }
}
@media (prefers-color-scheme: dark) { :root { --bg: #111; } }

.card-host { container: card / inline-size; }

.card { display: grid; gap: .5rem; }

@container card (min-width: 30rem) {
  .card { grid-template-columns: 8rem 1fr; }
  .card h3 { font-size: clamp(1rem, 4cqi, 1.5rem); }
}

:root { --color-primary: #2563eb; --radius: 8px; }
[data-theme="dark"] { --color-primary: #60a5fa; }

.btn {
  background: var(--color-primary);
  border-radius: var(--btn-radius, var(--radius));
}

@property --angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.spinner {
  background: conic-gradient(from var(--angle), red, blue);
  transition: --angle 1s;
}
.spinner:hover { --angle: 180deg; }

/* globalnie – BEM */
.card { }
.card__title { }
.card--featured { }

/* w komponencie (Emulated) – proste nazwy */
:host { display: block; }
:host(.featured) .title { color: var(--card-accent, inherit); }

.drawer {
  transform: translateX(-100%);
  transition: transform 200ms ease-out;
}
.drawer.open { transform: none; }

@media (prefers-reduced-motion: reduce) {
  .drawer { transition: none; }
}

// źle: layout w każdej iteracji
for (const el of items) {
  el.style.width = box.offsetWidth + 'px';
}
// dobrze: najpierw odczyty, potem zapisy
const w = box.offsetWidth;
for (const el of items) el.style.width = w + 'px';

async function processAll(items: Item[]) {
  for (let i = 0; i < items.length; i++) {
    process(items[i]);
    if (i % 200 === 0) {
      // oddaj wątek: przeglądarka może odmalować i obsłużyć input
      await new Promise(r => setTimeout(r));
    }
  }
}

